    context=[ex("Camila y su mamá compran verduras en la feria, después van a la peluquería a cortarle el pelo a Camila y un conductor de micro las lleva a casa. Clasifica: ¿cuántos servicios hubo?", "2: cortar el pelo y llevarlas a casa", "Son ayudas hechas por personas.")],
